<div class="dashboard-kpi-grid grid grid-cols-2 lg:grid-cols-5 gap-2 md:gap-4">
  <div class="hidden bg-white p-3.5 md:p-4 rounded-xl md:rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden col-span-2 md:col-span-1">
    <div class="absolute top-0 left-0 w-1.5 h-full bg-blue-500 rounded-l-2xl"></div>
    <p class="text-[9px] md:text-[10px] text-gray-500 font-bold uppercase tracking-wider mb-0.5 md:mb-1 truncate">Total Baki Debet (OS)</p>
    <h3 id="kpi_os" class="text-lg md:text-xl xl:text-2xl font-black text-gray-900 tracking-tight whitespace-nowrap mb-1.5 md:mb-2.5"><span class="kpi-loading-spinner" role="status" aria-label="Memuat data"></span></h3>
    <div id="kpi_os_pill"></div>
  </div>
  <div class="kpi-card kpi-card--saldo min-w-0 bg-white p-2.5 sm:p-3.5 md:p-4 rounded-xl md:rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden col-span-1">
    <div class="absolute top-0 left-0 w-1.5 h-full bg-cyan-500 rounded-l-2xl"></div>
    <p class="text-[8px] sm:text-[9px] md:text-[10px] text-gray-500 font-bold uppercase tracking-wider mb-0.5 md:mb-1 truncate">Saldo Bank</p>
    <h3 id="kpi_saldobank" class="text-[15px] sm:text-lg md:text-xl xl:text-2xl font-black text-cyan-600 tracking-tight whitespace-nowrap mb-1.5 md:mb-2.5"><span class="kpi-loading-spinner" role="status" aria-label="Memuat data"></span></h3>
    <div id="kpi_saldobank_pill" class="kpi-pill"></div>
  </div>
  <div class="kpi-card kpi-card--npl min-w-0 bg-white p-2.5 sm:p-3.5 md:p-4 rounded-xl md:rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden col-span-1">
    <div class="absolute top-0 left-0 w-1.5 h-full bg-red-500 rounded-l-2xl"></div>
    <p class="text-[8px] sm:text-[9px] md:text-[10px] text-gray-500 font-bold uppercase tracking-wider mb-0.5 md:mb-1 truncate">Total NPL (Saldo Bank)</p>
    <h3 id="kpi_npl" class="text-[15px] sm:text-lg md:text-xl xl:text-2xl font-black text-red-600 tracking-tight whitespace-nowrap mb-1.5 md:mb-2.5"><span class="kpi-loading-spinner" role="status" aria-label="Memuat data"></span></h3>
    <div id="kpi_npl_pill" class="kpi-pill"></div>
  </div>
  <div class="kpi-card kpi-card--rr min-w-0 bg-white p-2.5 sm:p-3.5 md:p-4 rounded-xl md:rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden col-span-1">
    <div class="absolute top-0 left-0 w-1.5 h-full bg-green-500 rounded-l-2xl"></div>
    <p class="text-[8px] sm:text-[9px] md:text-[10px] text-gray-500 font-bold uppercase tracking-wider mb-0.5 md:mb-1 truncate">Repayment Rate (RR)</p>
    <h3 id="kpi_rr" class="text-[15px] sm:text-lg md:text-xl xl:text-2xl font-black text-green-600 tracking-tight whitespace-nowrap mb-1.5 md:mb-2.5"><span class="kpi-loading-spinner" role="status" aria-label="Memuat data"></span></h3>
    <div id="kpi_rr_pill" class="kpi-pill"></div>
  </div>
  <div class="kpi-card kpi-card--dpk min-w-0 bg-white p-2.5 sm:p-3.5 md:p-4 rounded-xl md:rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden col-span-1">
    <div class="absolute top-0 left-0 w-1.5 h-full bg-purple-500 rounded-l-2xl"></div>
    <p class="text-[8px] sm:text-[9px] md:text-[10px] text-gray-500 font-bold uppercase tracking-wider mb-0.5 md:mb-1 truncate">Total Simpanan</p>
    <h3 id="kpi_dpk" class="text-[15px] sm:text-lg md:text-xl xl:text-2xl font-black text-purple-700 tracking-tight whitespace-nowrap mb-1.5 md:mb-2.5"><span class="kpi-loading-spinner" role="status" aria-label="Memuat data"></span></h3>
    <p id="kpi_dpk_date" class="kpi-date-label" title="Tanggal actual">Actual -</p>
    <div id="kpi_dpk_pill" class="kpi-pill">
      <span class="text-[9px] md:text-[11px] text-gray-400 font-semibold">Acc history 204</span>
    </div>
  </div>
  <div class="kpi-card kpi-card--laba min-w-0 bg-white p-2.5 sm:p-3.5 md:p-4 rounded-xl md:rounded-2xl shadow-sm border border-gray-100 relative overflow-hidden col-span-1">
    <div class="absolute top-0 left-0 w-1.5 h-full bg-indigo-500 rounded-l-2xl"></div>
    <p class="text-[8px] sm:text-[9px] md:text-[10px] text-gray-500 font-bold uppercase tracking-wider mb-0.5 md:mb-1 truncate">Laba Sebelum Pajak</p>
    <h3 id="kpi_laba" class="text-[15px] sm:text-lg md:text-xl xl:text-2xl font-black text-indigo-700 tracking-tight whitespace-nowrap mb-1.5 md:mb-2.5"><span class="kpi-loading-spinner" role="status" aria-label="Memuat data"></span></h3>
    <p id="kpi_laba_date" class="kpi-date-label" title="Tanggal actual">Actual -</p>
    <div id="kpi_laba_pill" class="kpi-pill">
      <span class="text-[9px] md:text-[11px] text-gray-400 font-semibold">Acc history 4 - 5</span>
    </div>
  </div>
</div>
